"use client";

import React from "react";

// --- インラインSVGアイコン ---
// 失敗/待機を示すアイコン
const AlertTriangleIcon = (props) => (
  <svg
    {...props}
    xmlns="http://www.w3.org/2000/svg"
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    className="w-6 h-6"
  >
    <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
    <line x1="12" y1="9" x2="12" y2="13" />
    <line x1="12" y1="17" x2="12.01" y2="17" />
  </svg>
);
// --- /インラインSVGアイコン ---

// ログデータをそのまま表示するコンポーネント
const StatusItem = ({ label, status, detail, isCritical = false }) => {
  const colorClass = isCritical
    ? "border-red-600 text-red-800 bg-red-100 font-bold"
    : "border-gray-400 text-gray-700 bg-gray-50";

  return (
    <li
      className={`p-4 rounded-lg border-2 ${colorClass} transition-all duration-300`}
    >
      <div className="flex items-center justify-between">
        <span className="font-semibold">{label}</span>
        <div className="flex items-center space-x-2">
          {isCritical && <AlertTriangleIcon className="w-5 h-5 text-red-600" />}
          <span
            className={`font-bold text-sm ${
              isCritical ? "text-red-600" : "text-gray-500"
            }`}
          >
            {status}
          </span>
        </div>
      </div>
      {detail && (
        <p
          className={`text-xs mt-2 break-all ${
            isCritical ? "text-red-700" : "text-gray-500"
          }`}
        >
          {detail}
        </p>
      )}
    </li>
  );
};

export default function App() {
  // ユーザーから提供されたログの値をハードコードして表示
  const logData = {
    appId: {
      status: "代替処理",
      detail:
        "未定義。アプリケーションIDは「default-app-id」としてフォールバック。",
      isCritical: false,
    },
    config: {
      status: "失敗/欠落",
      detail: "欠落またはJSONパースエラーの可能性。",
      isCritical: true,
      errorMessage: "__firebase_configが未定義またはnullです。",
    },
    authToken: {
      status: "代替処理",
      detail: "トークンなし。代わりに匿名認証を試行します。",
      isCritical: false,
    },
    init: {
      status: "失敗/欠落",
      detail: "初期化設定に問題があります。",
      isCritical: true,
    },
    auth: {
      status: "失敗/欠落",
      detail: "認証に失敗したか、トークンが期限切れです。",
      isCritical: true,
    },
  };

  const overallMessage = "エラーが発生しました。詳細を確認してください。";
  const overallBg = "bg-red-600";

  return (
    <div className="min-h-screen flex items-start justify-center bg-gray-50 p-8 font-inter">
      <div className="w-full max-w-2xl bg-white p-8 rounded-2xl shadow-xl border border-gray-200">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-extrabold text-gray-900 mt-3">
            Firebase 環境診断ツール（next.js 16）
          </h1>
          <p className="text-gray-500 mt-1">
            Canvas環境からのグローバル変数注入と認証プロセスを検証します。
          </p>
        </div>

        {/* 全体エラーメッセージ */}
        <div
          className={`p-5 rounded-xl font-bold text-white text-center mb-8 ${overallBg}`}
        >
          <div className="flex items-center justify-center">
            <AlertTriangleIcon className="w-6 h-6 mr-3 text-white" />
            {overallMessage}
          </div>
        </div>

        {/* 1. グローバル変数の状態 */}
        <h2 className="text-xl font-semibold text-gray-700 mb-4 border-b pb-2">
          1. グローバル変数の読み込み
        </h2>
        <ul className="space-y-3 mb-8">
          <StatusItem
            label="__app_id"
            status={logData.appId.status}
            detail={logData.appId.detail}
            isCritical={logData.appId.isCritical}
          />
          <StatusItem
            label="__firebase_config (JSON)"
            status={logData.config.status}
            detail={logData.config.detail}
            isCritical={logData.config.isCritical}
          />
          <StatusItem
            label="__initial_auth_token"
            status={logData.authToken.status}
            detail={logData.authToken.detail}
            isCritical={logData.authToken.isCritical}
          />
        </ul>

        {/* 2. Firebase サービスの状態 */}
        <h2 className="text-xl font-semibold text-gray-700 mb-4 border-b pb-2">
          2. Firebase サービスの初期化と認証
        </h2>
        <ul className="space-y-3 mb-8">
          <StatusItem
            label="Firebase App / Firestore 初期化"
            status={logData.init.status}
            detail={logData.init.detail}
            isCritical={logData.init.isCritical}
          />
          <StatusItem
            label="ユーザー認証状態 (Auth)"
            status={logData.auth.status}
            detail={logData.auth.detail}
            isCritical={logData.auth.isCritical}
          />
        </ul>

        {/* 発生したエラー */}
        {logData.config.errorMessage && (
          <div className="bg-red-500 p-4 rounded-xl text-white mt-6 font-mono text-sm border-2 border-red-800 shadow-lg">
            <span className="font-semibold block text-lg mb-2">
              発生した根本原因のエラー:
            </span>
            <span className="break-all font-bold">
              {logData.config.errorMessage}
            </span>
            <p className="mt-3 text-sm">
              **【重要】**
              このエラーは、Reactコンポーネントのコードではなく、このアプリケーションを実行している**プラットフォーム（Canvas実行環境）**側で、
              <code className="bg-red-700 p-1 rounded">__firebase_config</code>{" "}
              のグローバル変数が注入されていないことが原因です。この問題を解決するには、環境設定の確認が必要です。
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
